<?php if($role==='admin'):?><div class="stats-grid"><article class="stat-card"><span>Numerar disponibil în fond</span><strong><?=ron($reconciliation['cash'])?> lei</strong><small>Încasări minus plăți reale</small></article><article class="stat-card"><span>Credit pasageri disponibil</span><strong><?=ron($reconciliation['credit'])?> lei</strong><small>Distinct de numerarul din fond</small></article></div><section class="card"><h2>Înregistrează o mișcare de numerar</h2><form class="form-grid" data-command="fund" data-financial><?php selectParticipant($participants);?><label>Tip<select name="kind"><option value="contribution_received">Contribuție încasată</option><option value="reimbursement_paid">Rambursare plătită</option></select></label><label>Sumă (lei)<input name="amount" inputmode="decimal" required></label><label>Referință document<input name="reference" required></label><button class="button">Înregistrează plata</button></form></section><section class="card"><h2>Pregătește un decont</h2><p class="fine">Include doar înregistrările încă nedecontate până la data aleasă, inclusiv corecțiile ulterioare perioadelor deja aprobate.</p><form class="inline-form" data-command="settlement-create" data-financial><?php selectParticipant($participants);?><label>Până la data<input type="date" name="period_end" required></label><button class="button secondary">Creează decont</button></form></section><?php endif ?>
<section class="card"><h2>Deconturi</h2><?php foreach($settlements as $s):$snapshot=json_decode($s['snapshot'],true);?><article class="divided"><div class="section-heading"><h3><?=e($s['name'])?> · până la <?=e($s['period_end'])?></h3><span class="pill"><?=state($s['status'])?></span></div><p>Rambursări datorate: <?=ron($snapshot['reimbursement_due']??0)?> lei · Contribuții datorate: <?=ron($snapshot['contribution_due']??0)?> lei · Plătit prin decont: <?=ron($s['paid'])?> lei</p><p class="fine">Fotografie a registrului la creare. Plățile se înregistrează manual pe baza documentelor.</p><?php if($role==='admin'):?><form class="form-grid" data-command="settlement-update" data-financial><input type="hidden" name="id" value="<?=e($s['id'])?>"><label>Pasul următor<select name="status"><option value="under_review">În verificare</option><option value="approved">Aprobat</option><option value="partially_paid">Înregistrează plată</option><option value="paid">Plătit integral</option></select></label><label>Sumă plată (lei)<input name="amount" inputmode="decimal"></label><label>Referință<input name="reference"></label><button class="button secondary">Actualizează decontul</button></form><?php endif ?></article><?php endforeach ?><?php if(!$settlements):?><p class="empty">Niciun decont încă. Rapoartele fondului arată înregistrările la zi.</p><?php endif ?><a href="?role=<?=e($role)?>&amp;section=reports">Deschide raportul de decont →</a></section>
